<script setup>
import {ref,computed,onMounted} from 'vue'
import {api} from '../lib/api'
import {useQuests} from '../stores/quests'
import {useArcade} from '../stores/arcade'
const s=useArcade(),book=ref({units:[]}),subject=ref(''),unit=ref(''),busy=ref(false),claiming=ref(''),error=ref(''),notice=ref('')
const subjects=computed(()=>[...new Map(book.value.units.map(u=>[u.subject,u.subjectName])).entries()]),units=computed(()=>book.value.units.filter(u=>(!subject.value||u.subject===subject.value)&&(!unit.value||String(u.unit)===unit.value))),choices=computed(()=>book.value.units.filter(u=>u.subject===subject.value))
async function load(){busy.value=true;error.value='';try{book.value=await api('/quests');useQuests().accept(book.value);}catch(e){error.value=e.message}finally{busy.value=false}}
async function claim(q){if(claiming.value)return;claiming.value=q.id;error.value='';notice.value='';try{const r=await api('/quests/claim',{method:'POST',body:{questId:q.id}});notice.value=r.awarded?`퀘스트 완료! ${r.awarded}P를 받았어요.`:'이미 보상을 받았어요.';await Promise.all([load(),s.refresh()])}catch(e){error.value=e.message}finally{claiming.value=''}}
async function claimAll(){if(claiming.value||busy.value)return;claiming.value='all';error.value='';notice.value='';try{const result=await api('/quests/claim-all',{method:'POST',body:{}});notice.value=result.count?`퀘스트 ${result.count}개 보상 ${result.awarded}P를 한 번에 받았어요!`:'수령할 보상이 없어요.';await Promise.all([load(),s.refresh()])}catch(e){error.value=e.message}finally{claiming.value=''}}
onMounted(load)
</script>
<template><section class="quest-book"><div class="quest-book-heading"><div><p class="eyebrow">MY QUEST BOOK</p><h1>📖 퀘스트북</h1><p>단원마다 10개의 모험! 퀴즈·복습에서 서로 다른 문제를 맞혀 보세요.</p></div><RouterLink class="button light" to="/quiz">퀴즈 풀러 가기 →</RouterLink></div><div class="panel quest-controls"><label>과목<select v-model="subject" @change="unit='' "><option value="">전체 과목</option><option v-for="[id,name] in subjects" :key="id" :value="id">{{name}}</option></select></label><label>단원<select v-model="unit" :disabled="!subject"><option value="">전체 단원</option><option v-for="u in choices" :key="u.unit" :value="String(u.unit)">{{u.title}}</option></select></label><button :disabled="busy||!!claiming" @click="load">새로고침</button></div><div class="quest-claim-all panel"><div><b>완료한 퀘스트 {{book.ready??0}}개</b><small>선택한 필터와 관계없이 모든 과목의 수령 가능한 보상을 받아요.</small></div><button :disabled="busy||!!claiming||!book.ready" @click="claimAll">{{claiming==='all'?'일괄 수령 중…':'완료 보상 일괄 수령'}}</button></div><p class="quest-help">기존 퀴즈 기록도 반영돼요. 같은 문제의 반복 정답·수정 버전은 한 문제로 계산하며, 각 퀘스트 보상은 한 번만 받을 수 있어요. 학습자료의 완료 표시는 정답 수에 포함되지 않아요.</p><p v-if="error" role="alert" class="notice">{{error}}</p><p v-if="notice" role="status" class="notice">{{notice}}</p><p v-if="busy" role="status">퀘스트북을 불러오고 있어요…</p><p v-else-if="!units.length">등록된 단원이 없어요.</p><details v-for="u in units" :key="u.subject+u.unit" class="panel quest-unit" :open="!!subject||!u.locked"><summary><b>{{u.subjectName}} · {{u.title}}</b><span>{{u.locked?'🔒 공개 대기':`${u.quests.filter(q=>q.claimed).length} / 10 완료 · 정답 ${u.correct} / ${u.total}`}}</span></summary><p v-if="u.locked">아직 배우지 않은 단원입니다. 공개되면 도전할 수 있어요.</p><RouterLink v-if="!u.locked" class="button light" :to="{path:'/quiz',query:{subject:u.subject,unit:u.unit}}">이 단원 퀴즈 도전 →</RouterLink><div class="quest-grid"><article v-for="q in u.quests" :key="q.id" :class="['quest-card',{claimed:q.claimed,ready:q.ready}]"><div class="quest-tier">QUEST {{String(q.tier).padStart(2,'0')}} <b>🪙 {{q.reward}} P</b></div><h3>{{q.title}}</h3><progress :value="q.progress" :max="q.target"/><small>{{q.progress}} / {{q.target}}</small><button :disabled="u.locked||!q.ready||!!claiming" @click="claim(q)">{{q.claimed?'✓ 보상 수령 완료':u.locked?'🔒 잠김':claiming===q.id?'수령 중…':q.ready?'보상 받기':'도전 중'}}</button></article></div></details></section></template>
<style scoped>
.quest-claim-all{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:14px 16px}.quest-claim-all small{display:block;margin-top:8px;font-size:11px;line-height:1.6}.quest-book{max-width:1500px;margin:auto}.quest-book-heading,.quest-controls{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}.quest-book-heading h1{margin:6px 0}.quest-controls{margin:16px 0;padding:16px}.quest-controls label{flex:1;min-width:180px}.quest-controls select{width:100%;margin-top:6px}.quest-help{font-size:.9rem;line-height:1.7}.quest-unit{margin:18px 0;padding:18px}.quest-unit summary{cursor:pointer;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:6px 0 14px}.quest-grid{margin-top:14px;display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px}.quest-card{border:2px solid currentColor;border-radius:8px;padding:14px;display:flex;flex-direction:column;gap:10px;background:color-mix(in srgb,currentColor 4%,white);box-shadow:3px 4px 0 color-mix(in srgb,currentColor 25%,transparent)}.quest-card h3{font-size:1rem;min-height:2.6em;margin:4px 0;line-height:1.4}.quest-tier{display:flex;justify-content:space-between;font-size:.8rem;gap:8px}.quest-card progress{width:100%;height:12px}.quest-card button{margin-top:auto}.quest-card.ready{outline:3px solid currentColor;outline-offset:2px}.quest-card.claimed{opacity:.7}.quest-book button:disabled{cursor:default}@media(max-width:600px){.quest-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.quest-card{padding:10px;min-width:0}.quest-card h3{font-size:.85rem}.quest-tier{flex-direction:column}.quest-unit{padding:12px}.quest-controls{align-items:stretch}.quest-controls label{min-width:100%}.quest-book-heading .button{width:100%;text-align:center}}@media(max-width:350px){.quest-grid{grid-template-columns:1fr}}
</style>
